```js
class ProgressService {
  #logger; #storage;
  constructor({ logger, storage }) {      // parts passed in.
    this.#logger = logger;
    this.#storage = storage;
  }
  complete(lessonId) {
    this.#storage.save(`done:${lessonId}`, true);
    this.#logger.log(`completed ${lessonId}`);
  }
}

// In the app.
const service = new ProgressService({
  logger: console,
  storage: { save: (k, v) => localStorage.setItem(k, JSON.stringify(v)) },
});

// In a test: fakes with the same small interface.
const saved = [];
const testService = new ProgressService({
  logger: { log() {} },
  storage: { save: (k, v) => saved.push([k, v]) },
});
```

